-- Horse Soldier importer (bourbon.horse_soldier), applied 2026-10-12
-- Barrel Strength's 121.5 proof is the hand-read label in the maker's own photo (image HSB19073_BarrelStrengthStack, Shopify id 43121065525463); the page states no proof in text.
-- Left alone: seed 'Horse Soldier Single Barrel' (87 pf) is not on the site; absence is not proof it is gone.
update cellar.products set age_years = 4.0, age_label = '4 yr', nas = false, producer = coalesce(producer, 'Horse Soldier'), producer_id = coalesce(producer_id, '7cdb81ae-06ad-4f1f-97e1-d9be47ef6c97'::uuid), source = 'maker', source_url = 'https://horsesoldierbourbon.com/products/straight-bourbon-whiskey', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity) where id = '849714fa-4d20-450a-933c-b560255727f4' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('849714fa-4d20-450a-933c-b560255727f4');
update cellar.makers set website = coalesce(website, 'https://horsesoldierbourbon.com'), country = coalesce(country, 'US'), updated_at = now() where id = '7cdb81ae-06ad-4f1f-97e1-d9be47ef6c97';
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
