s://horsesoldierbourbon.com/cdn/shop/files/signature.webp?v=1682966738","u":"https://horsesoldierbourbon.com/products/small-batch-bourbon-whiskey","pr":"Horse Soldier","mk":"7cdb81ae-06ad-4f1f-97e1-d9be47ef6c97"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');